function treesFor(ids) {
	const seen = /* @__PURE__ */ new Set();
	const out = [];
	for (const id of ids) {
		const t = METABOLITE_TREES[id];
		if (t && !seen.has(t.id)) {
			seen.add(t.id);
			out.push(t);
		}
	}
	return out;
}
function sampleNeedsPro(s) {
	return Boolean(s.phenotypes || s.smoking || s.alcohol || s.cannabisRoute);
}
